```tsx
import { useState, useCallback } from "react";
import type { ActionFunctionArgs, HeadersFunction, LoaderFunctionArgs } from "react-router";
import { useActionData, useNavigation, Form, redirect } from "react-router";
import {
  Page, Layout, Card, Text, InlineStack, BlockStack,
  Button, TextField, Select, RadioButton, Banner,
  SkeletonPage, SkeletonBodyText,
} from "@shopify/polaris";
import { useAppBridge } from "@shopify/app-bridge-react";
import { useEffect } from "react";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";
import db from "../db.server";

export const loader = async ({ request }: LoaderFunctionArgs) => {
  await authenticate.admin(request);
  return null;
};

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();
  const title = String(formData.get("title") ?? "").trim();
  const type = String(formData.get("type") ?? "product-recommendation");
  const description = String(formData.get("description") ?? "").trim() || null;

  if (!title) {
    return { error: "Quiz title is required" };
  }

  try {
    // Check plan limits
    const count = await db.quiz.count({ where: { shop: session.shop, status: { not: "archived" } } });
    // Simple free plan check - 1 quiz limit
    const sub = await db.subscription.findUnique({ where: { shop: session.shop }, select: { planId: true } });
    const planId = sub?.planId ?? "free";
    const limits: Record<string, number> = { free: 1, starter: 5, pro: 999, enterprise: 999 };
    const limit = limits[planId] ?? 1;
    if (count >= limit) {
      return { error: `You've reached the ${limit}-quiz limit for your plan. Please upgrade to create more quizzes.` };
    }

    // Generate slug
    const base = title.toLowerCase().replace(/[^a-z0-9\s-]/g, "").replace(/\s+/g, "-").replace(/-+/g, "-").replace(/^-|-$/g, "") || "quiz";
    let slug = base;
    let counter = 0;
    while (await db.quiz.findFirst({ where: { shop: session.shop, slug } })) {
      counter++;
      slug = `${base}-${counter}`;
    }

    const quiz = await db.quiz.create({
      data: { shop: session.shop, title, slug, type, description },
    });

    return redirect(`/app/quizzes/${quiz.id}`);
  } catch (error) {
    console.error("Create quiz error:", error);
    return { error: "Failed to create quiz. Please try again." };
  }
};

const QUIZ_TYPES = [
  { value: "product-recommendation", label: "Product Recommendation", description: "Guide shoppers to the right product" },
  { value: "personality", label: "Personality Quiz", description: "Reveal a personality type or style profile" },
  { value: "assessment", label: "Assessment", description: "Evaluate needs (skin type, fitness level, etc.)" },
  { value: "survey", label: "Survey", description: "Collect feedback and preferences" },
  { value: "lead-gen", label: "Lead Generation", description: "Capture emails and contact info" },
];

export default function NewQuizPage() {
  const actionData = useActionData<typeof action>();
  const navigation = useNavigation();
  const shopify = useAppBridge();
  const isSubmitting = navigation.state === "submitting";

  const [title, setTitle] = useState("");
  const [type, setType] = useState("product-recommendation");
  const [description, setDescription] = useState("");

  useEffect(() => {
    if (actionData && "error" in actionData && actionData.error) {
      shopify.toast.show(actionData.error, { isError: true });
    }
  }, [actionData, shopify]);

  return (
    <Page
      title="Create quiz"
      backAction={{ content: "Quizzes", url: "/app/quizzes" }}
    >
      <Layout>
        <Layout.Section>
          <Form method="post">
            <input type="hidden" name="type" value={type} />
            <BlockStack gap="500">
              {actionData && "error" in actionData && actionData.error && (
                <Banner tone="critical" title="Error">
                  <p>{actionData.error}</p>
                </Banner>
              )}

              <Card>
                <BlockStack gap="400">
                  <Text as="h2" variant="headingMd">Quiz type</Text>
                  <BlockStack gap="300">
                    {QUIZ_TYPES.map((qt) => (
                      <div
                        key={qt.value}
                        style={{
                          padding: "12px 16px",
                          border: `2px solid ${type === qt.value ? "var(--p-color-border-emphasis)" : "var(--p-color-border)"}`,
                          borderRadius: "var(--p-border-radius-300)",
                          cursor: "pointer",
                          background: type === qt.value ? "var(--p-color-bg-surface-secondary)" : "transparent",
                          transition: "border-color 0.15s",
                        }}
                        onClick={() => setType(qt.value)}
                        role="button"
                        tabIndex={0}
                        onKeyDown={(e) => { if (e.key === "Enter") setType(qt.value); }}
                      >
                        <InlineStack gap="300" blockAlign="center">
                          <RadioButton
                            label=""
                            labelHidden
                            checked={type === qt.value}
                            id={qt.value}
                            name="quiz-type"
                            onChange={() => setType(qt.value)}
                          />
                          <BlockStack gap="050">
                            <Text as="p" variant="bodyMd" fontWeight="semibold">{qt.label}</Text>
                            <Text as="p" variant="bodySm" tone="subdued">{qt.description}</Text>
                          </BlockStack>
                        </InlineStack>
                      </div>
                    ))}
                  </BlockStack>
                </BlockStack>
              </Card>

              <Card>
                <BlockStack gap="400">
                  <Text as="h2" variant="headingMd">Quiz details</Text>
                  <TextField
                    label="Quiz title"
                    name="title"
                    value={title}
                    onChange={setTitle}
                    placeholder="e.g., Find Your Perfect Skincare Routine"
                    autoComplete="off"
                    helpText="This is shown to customers on your storefront"
                    requiredIndicator
                  />
                  <TextField
                    label="Description (optional)"
                    name="description"
                    value={description}
                    onChange={setDescription}
                    placeholder="Brief description of what this quiz helps customers find"
                    multiline={3}
                    autoComplete="off"
                  />
                </BlockStack>
              </Card>

              <InlineStack align="end" gap="300">
                <Button url="/app/quizzes">Cancel</Button>
                <Button
                  submit
                  variant="primary"
                  loading={isSubmitting}
                  disabled={!title.trim() || isSubmitting}
                >
                  Create quiz
                </Button>
              </InlineStack>
            </BlockStack>
          </Form>
        </Layout.Section>
      </Layout>
    </Page>
  );
}

export function HydrateFallback() {
  return (
    <SkeletonPage title="Create quiz" backAction>
      <Layout>
        <Layout.Section>
          <SkeletonBodyText lines={8} />
        </Layout.Section>
      </Layout>
    </SkeletonPage>
  );
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};
