import { useEffect } from "react";
import { json } from "react-router";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";
import db from "../db.server";

const PLANS = [
  {
    id: "free",
    name: "Free",
    price: "$0",
    period: "forever",
    quizLimit: 1,
    responseLimit: "100/mo",
    features: ["1 active quiz", "100 responses/month", "Basic analytics", "QuizSnap branding"],
    notIncluded: ["Email integrations", "A/B testing", "CSV export", "Custom branding"],
    cta: "Current plan",
    highlight: false,
  },
  {
    id: "starter",
    name: "Starter",
    price: "$9.99",
    period: "/month",
    quizLimit: 5,
    responseLimit: "1,000/mo",
    features: ["5 active quizzes", "1,000 responses/month", "Basic analytics", "1 email integration", "Remove branding"],
    notIncluded: ["A/B testing", "CSV export", "Custom branding"],
    cta: "Upgrade to Starter",
    highlight: false,
  },
  {
    id: "pro",
    name: "Pro",
    price: "$29.99",
    period: "/month",
    quizLimit: -1,
    responseLimit: "10,000/mo",
    features: ["Unlimited quizzes", "10,000 responses/month", "Full analytics", "All integrations", "A/B testing", "CSV export", "Custom branding"],
    notIncluded: [],
    cta: "Upgrade to Pro",
    highlight: true,
  },
  {
    id: "enterprise",
    name: "Enterprise",
    price: "$79.99",
    period: "/month",
    quizLimit: -1,
    responseLimit: "Unlimited",
    features: ["Everything in Pro", "Unlimited responses", "API access", "Priority support", "Custom widget domain"],
    notIncluded: [],
    cta: "Upgrade to Enterprise",
    highlight: false,
  },
];

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);

  try {
    const [sub, quizCount, responseCount] = await Promise.all([
      db.subscription.findUnique({ where: { shop: session.shop } }),
      db.quiz.count({ where: { shop: session.shop, status: { not: "archived" } } }),
      db.quizResponse.count({ where: { shop: session.shop, createdAt: { gte: new Date(new Date().setDate(1)) } } }),
    ]);

    return json({
      currentPlan: sub?.planId ?? "free",
      status: sub?.status ?? "active",
      quizCount,
      responseCount,
    });
  } catch (error) {
    console.error("Billing loader error:", error);
    throw json({ error: "Failed to load billing information" }, { status: 500 });
  }
};

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();
  const planId = String(formData.get("planId") ?? "");

  try {
    if (planId === "free") {
      await db.subscription.upsert({
        where: { shop: session.shop },
        create: { shop: session.shop, planId: "free", status: "active", quizLimit: 1, responseLimit: 100 },
        update: { planId: "free", status: "active" },
      });
      return json({ success: true, message: "Downgraded to Free plan" });
    }

    // In production, this would redirect to Shopify billing
    // For now, update subscription directly (for dev/testing)
    const limits: Record<string, { quizLimit: number; responseLimit: number }> = {
      starter: { quizLimit: 5, responseLimit: 1000 },
      pro: { quizLimit: 999, responseLimit: 10000 },
      enterprise: { quizLimit: 999, responseLimit: 999999 },
    };

    await db.subscription.upsert({
      where: { shop: session.shop },
      create: { shop: session.shop, planId, status: "active", ...(limits[planId] ?? { quizLimit: 1, responseLimit: 100 }) },
      update: { planId, status: "active", ...(limits[planId] ?? {}) },
    });

    return json({ success: true, message: `Upgraded to ${planId} plan successfully!` });
  } catch (error) {
    console.error("Billing action error:", error);
    return json({ error: "Failed to update plan. Please try again." }, { status: 500 });
  }
};

export default function BillingPage() {
  const { currentPlan, quizCount, responseCount } = useLoaderData<typeof loader>();
  const actionData = useActionData<typeof action>();
  const navigation = useNavigation();
  const shopify = useAppBridge();
  const isUpdating = navigation.state === "submitting";

  useEffect(() => {
    if (actionData && "success" in actionData && actionData.success) {
      shopify.toast.show(actionData.message ?? "Plan updated!", { duration: 4000 });
    }
    if (actionData && "error" in actionData) {
      shopify.toast.show(actionData.error, { isError: true });
    }
  }, [actionData, shopify]);

  const currentPlanData = PLANS.find((p) => p.id === currentPlan) ?? PLANS[0];

  return (
    <Page title="Plans & Billing" subtitle="Choose the right plan for your store">
      <BlockStack gap="600">
        {/* Current usage */}
        <Card>
          <BlockStack gap="400">
            <InlineStack align="space-between">
              <Text as="h2" variant="headingMd">Current plan</Text>
              <Badge tone={currentPlan === "free" ? undefined : "success"}>
                {currentPlanData.name}
              </Badge>
            </InlineStack>
            <InlineStack gap="600">
              <BlockStack gap="100">
                <Text as="p" variant="bodySm" tone="subdued">Active quizzes</Text>
                <Text as="p" variant="headingLg" fontWeight="bold">{quizCount}</Text>
                <Text as="p" variant="bodySm" tone="subdued">
                  of {currentPlanData.quizLimit === -1 ? "unlimited" : currentPlanData.quizLimit}
                </Text>
              </BlockStack>
              <BlockStack gap="100">
                <Text as="p" variant="bodySm" tone="subdued">Responses this month</Text>
                <Text as="p" variant="headingLg" fontWeight="bold">{responseCount.toLocaleString()}</Text>
                <Text as="p" variant="bodySm" tone="subdued">of {currentPlanData.responseLimit}</Text>
              </BlockStack>
            </InlineStack>
          </BlockStack>
        </Card>

        {/* Plan cards */}
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(240px, 1fr))", gap: "16px" }}>
          {PLANS.map((plan) => {
            const isCurrent = plan.id === currentPlan;
            return (
              <div
                key={plan.id}
                style={{
                  border: plan.highlight ? "2px solid var(--p-color-border-emphasis)" : "1px solid var(--p-color-border)",
                  borderRadius: "var(--p-border-radius-300)",
                  padding: "20px",
                  position: "relative",
                  background: isCurrent ? "var(--p-color-bg-surface-secondary)" : "var(--p-color-bg-surface)",
                }}
              >
                {plan.highlight && (
                  <div style={{ position: "absolute", top: -12, left: "50%", transform: "translateX(-50%)" }}>
                    <Badge tone="success">Most Popular</Badge>
                  </div>
                )}
                <BlockStack gap="400">
                  <BlockStack gap="100">
                    <Text as="h3" variant="headingMd" fontWeight="bold">{plan.name}</Text>
                    <InlineStack gap="100" blockAlign="end">
                      <Text as="span" variant="headingXl" fontWeight="bold">{plan.price}</Text>
                      <Text as="span" variant="bodyMd" tone="subdued">{plan.period}</Text>
                    </InlineStack>
                  </BlockStack>
                  <Divider />
                  <List type="bullet">
                    {plan.features.map((f) => (
                      <List.Item key={f}>{f}</List.Item>
                    ))}
                  </List>
                  <Form method="post">
                    <input type="hidden" name="planId" value={plan.id} />
                    <Button
                      submit
                      variant={plan.highlight ? "primary" : "secondary"}
                      disabled={isCurrent || isUpdating}
                      loading={isUpdating && navigation.formData?.get("planId") === plan.id}
                      fullWidth
                    >
                      {isCurrent ? "Current plan" : plan.cta}
                    </Button>
                  </Form>
                </BlockStack>
              </div>
            );
          })}
        </div>
      </BlockStack>
    </Page>
  );
}

export function HydrateFallback() {
  return (
    <SkeletonPage title="Plans & Billing">
      <SkeletonBodyText lines={10} />
    </SkeletonPage>
  );
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};
```

