import { authenticate } from "../shopify.server";
import db from "../db.server";

export const action = async ({ request }: { request: Request }) => {
  const { topic, shop, payload } = await authenticate.webhook(request);

  switch (topic) {
    case "CUSTOMERS_DATA_REQUEST":
      console.info(`Customer data request for shop ${shop}`);
      break;

    case "CUSTOMERS_REDACT":
      if (payload && typeof payload === "object" && "customer" in payload) {
        const customer = payload.customer as { email?: string };
        if (customer?.email) {
          await db.quizResponse.updateMany({
            where: { shop, email: customer.email },
            data: { email: null },
          });
        }
      }
      break;

    case "SHOP_REDACT":
      await Promise.all([
        db.quiz.deleteMany({ where: { shop } }),
        db.subscription.deleteMany({ where: { shop } }),
        db.widgetConfig.deleteMany({ where: { shop } }),
        db.emailIntegration.deleteMany({ where: { shop } }),
        db.productMapping.deleteMany({ where: { shop } }),
      ]);
      break;
  }

  return new Response(null, { status: 200 });
};
```

