export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);

  try {
    const startOfMonth = new Date();
    startOfMonth.setDate(1);
    startOfMonth.setHours(0, 0, 0, 0);

    const [sub, quizCount, responseCount] = await Promise.all([
      db.subscription.findUnique({ where: { shop: session.shop } }),
      db.quiz.count({
        where: { shop: session.shop, status: { not: "archived" } },
      }),
      db.quizResponse.count({
        where: {
          shop: session.shop,
          createdAt: { gte: startOfMonth },
        },
      }),
    ]);

    return json({
      currentPlan: (sub?.planId ?? "free") as PlanId,
      planStatus: sub?.status ?? "active",
      quizCount,
      responseCount,
      trialEndsAt: sub?.trialEndsAt?.toISOString() ?? null,
    });
  } catch (error) {
    console.error("Billing loader error:", error);
    throw json({ error: "Failed to load billing information" }, { status: 500 });
