export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);

  try {
    const [integrations, sub] = await Promise.all([
      db.emailIntegration.findMany({
        where: { shop: session.shop },
        select: {
          id: true,
          provider: true,
          apiKey: true,
          listId: true,
          isActive: true,
        },
        orderBy: { createdAt: "asc" },
      }),
      db.subscription.findUnique({
        where: { shop: session.shop },
        select: { planId: true },
      }),
    ]);

    const planId = sub?.planId ?? "free";

    // Mask API keys for display — keep first 4 and last 4 chars visible
    const masked = integrations.map((i) => ({
      ...i,
      provider: i.provider as Provider,
      apiKey:
        i.apiKey.length > 8
          ? `${i.apiKey.slice(0, 4)}${"•".repeat(Math.max(0, i.apiKey.length - 8))}${i.apiKey.slice(-4)}`
          : "••••••••",
    }));

    return json({ integrations: masked as IntegrationRecord[], planId });
  } catch (error) {
    console.error("Integrations loader error:", error);
    throw json({ error: "Failed to load integrations" }, { status: 500 });
  }
};

// ─── Action ───────────────────────────────────────────────────────────────────

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();
  const intent = String(formData.get("intent") ?? "");
  const provider = String(formData.get("provider") ?? "") as Provider;

  const validProviders: Provider[] = [
    "klaviyo",
    "mailchimp",
    "omnisend",
    "custom-webhook",
  ];
  if (!validProviders.includes(provider)) {
    return json({ error: "Invalid provider" }, { status: 400 });
  }

  try {
    if (intent === "connect") {
      const apiKey = String(formData.get("apiKey") ?? "").trim();
      const listId = String(formData.get("listId") ?? "").trim() || null;

      if (!apiKey) {
        return json(
          { error: "API key is required", provider },
          { status: 400 },
        );
      }

      // Plan gate — check before writing
      const sub = await db.subscription.findUnique({
        where: { shop: session.shop },
        select: { planId: true },
      });
      const planId = sub?.planId ?? "free";
      const config = PROVIDERS.find((p) => p.id === provider);

      if (!config) {
        return json({ error: "Unknown provider" }, { status: 400 });
      }

      const planOrder = ["free", "starter", "pro", "enterprise"];
      const currentIdx = planOrder.indexOf(planId);
      const requiredIdx = planOrder.indexOf(config.requiredPlan);

      if (currentIdx < requiredIdx) {
        return json(
          {
            error: `${config.name} requires the ${config.requiredPlan} plan or higher. Please upgrade.`,
            provider,
          },
          { status: 403 },
        );
      }

      await db.emailIntegration.upsert({
        where: { shop_provider: { shop: session.shop, provider } },
        create: {
          shop: session.shop,
          provider,
          apiKey,
          listId,
          isActive: true,
        },
        update: { apiKey, listId, isActive: true },
      });

      const providerName = config.name;
      return json({
        success: true,
        message: `${providerName} connected successfully!`,
        provider,
      });
    }

    if (intent === "disconnect") {
      await db.emailIntegration.deleteMany({
        where: { shop: session.shop, provider },
      });

      const providerName =
        PROVIDERS.find((p) => p.id === provider)?.name ?? provider;
      return json({
        success: true,
        message: `${providerName} disconnected`,
        provider,
      });
    }

    if (intent === "toggle") {
      const existing = await db.emailIntegration.findUnique({
        where: { shop_provider: { shop: session.shop, provider } },
      });
      if (!existing) {
        return json({ error: "Integration not found" }, { status: 404 });
      }
      await db.emailIntegration.update({
        where: { shop_provider: { shop: session.shop, provider } },
        data: { isActive: !existing.isActive },
      });
      return json({
        success: true,
        message: existing.isActive ? "Integration paused" : "Integration enabled",
        provider,
      });
    }

    return json({ error: "Unknown intent" }, { status: 400 });
  } catch (error) {
    console.error("Integrations action error:", error);
    return json(
      { error: "Action failed. Please try again." },
      { status: 500 },
    );
  }
};

