function PlanGateBanner({
  requiredPlan,
  currentPlan,
}: {
  requiredPlan: string;
  currentPlan: string;
}) {
  const planOrder = ["free", "starter", "pro", "enterprise"];
  const isGated =
    planOrder.indexOf(currentPlan) < planOrder.indexOf(requiredPlan);

  if (!isGated) return null;

  const label = requiredPlan.charAt(0).toUpperCase() + requiredPlan.slice(1);

  return (
    <Banner
      tone="warning"
      title={`${label} plan required`}
      action={{ content: "Upgrade now", url: "/app/billing" }}
    >
      <p>
        Upgrade to the {label} plan or higher to use this integration.
      </p>
    </Banner>
  );
}

