import type { ActionFunctionArgs } from "react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";

export const action = async ({ request }: ActionFunctionArgs) => {
  const { topic, shop, payload } = await authenticate.webhook(request);

  console.info(`Received ${topic} webhook for ${shop}`);

  switch (topic) {
    case "CUSTOMERS_DATA_REQUEST": {
      // GDPR: merchant is requesting data held for a customer.
      // Log the request — no PII deletion required at this stage.
      console.info(
        `[GDPR] Customer data request received for shop ${shop}`,
        payload,
      );
      break;
    }

    case "CUSTOMERS_REDACT": {
      // GDPR: erase personal data for a specific customer.
      if (payload && typeof payload === "object" && "customer" in payload) {
        const customer = payload.customer as {
          email?: string;
          phone?: string;
        };

        if (customer?.email) {
          try {
            await db.quizResponse.updateMany({
              where: { shop, email: customer.email },
              data: { email: null },
            });
            console.info(
              `[GDPR] Redacted email for customer ${customer.email} on shop ${shop}`,
            );
          } catch (error) {
            console.error(
              `[GDPR] Failed to redact customer data for ${shop}:`,
              error,
            );
          }
        }
      }
      break;
    }

    case "SHOP_REDACT": {
      // GDPR: 48 hours after uninstall, erase all shop data.
      // Check idempotency: only act if data still exists.
      try {
        const existing = await db.quiz.count({ where: { shop } });

        if (existing > 0) {
          await Promise.all([
            db.quiz.deleteMany({ where: { shop } }),
            db.subscription.deleteMany({ where: { shop } }),
            db.widgetConfig.deleteMany({ where: { shop } }),
            db.emailIntegration.deleteMany({ where: { shop } }),
            db.productMapping.deleteMany({ where: { shop } }),
            // QuizResponses and AnalyticsEvents cascade from Quiz deletion above,
            // but delete directly in case of orphaned records.
            db.quizResponse.deleteMany({ where: { shop } }),
          ]);

          console.info(`[GDPR] Shop redact complete for ${shop}`);
        } else {
          console.info(
            `[GDPR] Shop redact: no data found for ${shop}, skipping`,
          );
        }
      } catch (error) {
        console.error(`[GDPR] Shop redact failed for ${shop}:`, error);
        // Return 500 so Shopify retries the webhook
        return new Response(null, { status: 500 });
      }
      break;
    }

    default: {
      console.warn(`Unhandled webhook topic: ${topic} for shop ${shop}`);
      break;
    }
  }

  return new Response(null, { status: 200 });
};
